package com.example.bytequest

/** Curriculum-linked multiple-choice questions; playable offline. */
data class QuizQuestion(
    val id: String,
    val lessonId: String,
    val prompt: String,
    val options: List<String>,
    val correctIndex: Int,
    val explanation: String,
    /** Index of a specific key idea in the related student lesson. */
    val referencePoint: Int
)

data class StudySource(val title: String, val url: String)

/** New BQQ classroom codes select a deterministic, fixed-length lesson question set. */
data class QuizChallenge(val lessonId: String, val count: Int) {
    val code: String get() = "BQQ-$lessonId-$count"
}

