    /** Pack sizes 10 make a 50-question topic manageable on mobile. */
    fun tenQuestionPack(lessonId: String, packIndex: Int): List<QuizQuestion> =
        if (packIndex in 0..4) forLesson(lessonId).drop(packIndex * 10).take(10) else emptyList()


    fun makeQuizChallenge(lessonId: String, count: Int): QuizChallenge? =
        if (lessonId in GameContent.allTopics && count in 1..forLesson(lessonId).size)
            QuizChallenge(lessonId, count) else null

    fun parseQuizChallenge(raw: String): QuizChallenge? {
        val parts = raw.trim().uppercase().split('-')
        if (parts.size != 3 || parts[0] != "BQQ") return null
        return makeQuizChallenge(parts[1], parts[2].toIntOrNull() ?: return null)
    }

    fun challengeQuestionIds(challenge: QuizChallenge): List<String> =
        forLesson(challenge.lessonId).take(challenge.count).map { it.id }

    fun forLesson(id: String): List<QuizQuestion> = if (id == "ALL") questions else questions.filter { it.lessonId == id }
    fun findById(id: String): QuizQuestion? = questions.firstOrNull { it.id == id }
    fun correctOption(question: QuizQuestion): String = question.options[question.correctIndex]
    fun lessonReference(question: QuizQuestion): String {
        val lesson = GameContent.lessons.first { it.id == question.lessonId }
        return "${lesson.name} • Key idea ${question.referencePoint + 1}: ${lesson.keyIdeas[question.referencePoint]}"
    }
}
